import math

N = 78
total_paths = 0

# P(r, c) = number of paths from (0, 0) to (r, c) using only Right and Down moves
# P(r, c) = C(r+c, r)

for r in range(N):
    for c in range(N):
        # We calculate C(r+c, r)
        try:
            paths_to_cell = math.comb(r + c, r)
        except AttributeError:
            # Fallback for older Python versions if math.comb is missing
            def combinations(n, k):
                if k < 0 or k > n:
                    return 0
                if k == 0 or k == n:
                    return 1
                if k > n // 2:
                    k = n - k

                res = 1
                for i in range(k):
                    res = res * (n - i) // (i + 1)
                return res
            paths_to_cell = combinations(r + c, r)

        total_paths += paths_to_cell

print(total_paths)
